        // 3. Handle form submission
        form.addEventListener('submit', function(event) {
            event.preventDefault(); // Stop the page from refreshing

            // Get values from inputs
            const name = document.getElementById('name').value;
            const message = document.getElementById('message').value;

            // Create an object for the data
            const entry = {
                id: Date.now(), // Unique ID based on time
                name: name,
                message: message,
                date: new Date().toLocaleDateString()
            };

            // Save to Local Storage
            saveEntry(entry);

            // Clear the form
            form.reset();

            // Add to the list on screen
            addEntryToDOM(entry);
        });

        // Function to save to browser storage
        function saveEntry(entry) {
            let entries;
            if (localStorage.getItem('savedEntries') === null) {
                entries = [];
            } else {
                entries = JSON.parse(localStorage.getItem('savedEntries'));
            }
            entries.push(entry);
            localStorage.setItem('savedEntries', JSON.stringify(entries));
